            if (team.RivalTeamsOption.IsSet && team.RivalTeams == null)
                throw new ArgumentNullException(nameof(team.RivalTeams), "Property is required for class Team.");

            writer.WriteNumber("culture_score", team.CultureScore);

            writer.WriteNumber("founded_year", team.FoundedYear);

            writer.WriteString("id", team.Id);

            var leagueRawValue = LeagueValueConverter.ToJsonValue(team.League);
            writer.WriteString("league", leagueRawValue);

            writer.WriteString("name", team.Name);

            writer.WriteString("stadium", team.Stadium);

            writer.WritePropertyName("values");
            JsonSerializer.Serialize(writer, team.Values, jsonSerializerOptions);
            if (team.AnnualBudgetGbpOption.IsSet)
                if (team.AnnualBudgetGbpOption.Value != null)
                    writer.WriteString("annual_budget_gbp", team.AnnualBudgetGbp);
                else
                    writer.WriteNull("annual_budget_gbp");

            if (team.AverageAttendanceOption.IsSet)
                if (team.AverageAttendanceOption.Value != null)
                    writer.WriteNumber("average_attendance", team.AverageAttendanceOption.Value!.Value);
                else
                    writer.WriteNull("average_attendance");

            if (team.ContactEmailOption.IsSet)
                if (team.ContactEmailOption.Value != null)
                    writer.WriteString("contact_email", team.ContactEmail);
                else
                    writer.WriteNull("contact_email");

            if (team.IsActiveOption.IsSet)
                writer.WriteBoolean("is_active", team.IsActiveOption.Value!.Value);

            if (team.NicknameOption.IsSet)
                if (team.NicknameOption.Value != null)
                    writer.WriteString("nickname", team.Nickname);
                else
                    writer.WriteNull("nickname");

            if (team.PrimaryColorOption.IsSet)
                if (team.PrimaryColorOption.Value != null)
                    writer.WriteString("primary_color", team.PrimaryColor);
                else
                    writer.WriteNull("primary_color");

            if (team.RivalTeamsOption.IsSet)
            {
                writer.WritePropertyName("rival_teams");
                JsonSerializer.Serialize(writer, team.RivalTeams, jsonSerializerOptions);
            }
            if (team.SecondaryColorOption.IsSet)
                if (team.SecondaryColorOption.Value != null)
                    writer.WriteString("secondary_color", team.SecondaryColor);
                else
                    writer.WriteNull("secondary_color");

            if (team.StadiumLocationOption.IsSet)
                if (team.StadiumLocationOption.Value != null)
                {
                    writer.WritePropertyName("stadium_location");
                    JsonSerializer.Serialize(writer, team.StadiumLocation, jsonSerializerOptions);
                }
                else
                    writer.WriteNull("stadium_location");
            if (team.WebsiteOption.IsSet)
                if (team.WebsiteOption.Value != null)
                    writer.WriteString("website", team.Website);
                else
                    writer.WriteNull("website");

            if (team.WinPercentageOption.IsSet)
                if (team.WinPercentageOption.Value != null)
                    writer.WriteNumber("win_percentage", team.WinPercentageOption.Value!.Value);
                else
                    writer.WriteNull("win_percentage");
        }
    }
}
